window.__finlexDocLoaded(10230,{"id":10230,"articles":[{"id":1000978,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Distinguishes Recognized (Type 1) vs. Nonrecognized (Type 2) subsequent events occurring after the balance sheet date through the date financial statements are issued (SEC filers) or available to be issued (non-SEC entities).","seq":0},{"id":1000979,"no":"ASC 855-10","heading":"Type 1 Recognized vs. Type 2 Nonrecognized Events","text":"• Evaluation Cutoff (ASC 855-10-25): SEC filers evaluate subsequent events through the date financial statements are ISSUED; non-SEC entities evaluate through the date financial statements are AVAILABLE TO BE ISSUED (and must disclose that date).\n• Recognized vs. Nonrecognized: Conditions existing at the balance sheet date adjust financial statements; conditions arising after the balance sheet date are disclosed if material.","seq":1},{"id":1000980,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Cutoff Date: ASC 855 runs through the date financial statements are ISSUED (for SEC filers), whereas IAS 10.3 runs through the date financial statements are AUTHORIZED FOR ISSUE (typically slightly earlier).","seq":2},{"id":1000981,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
